let cleanup=()=>{};const main=document.querySelector('main');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function applyTheme(){document.documentElement.dataset.theme=theme;document.querySelector('#theme').textContent=theme==='dark'?text[lang].light:text[lang].dark;document.querySelector('#theme').setAttribute('aria-label',text[lang].themeLabel);}
