function renderHome(){const t=text[lang];main.innerHTML=`<section class="hero"><video muted loop playsinline preload="none" poster="${posterAsset}" aria-hidden="true" tabindex="-1"></video><div class="wrap hero-inner"><div class="hero-composition"><div class="hero-copy"><span class="eyebrow">${t.eyebrow}</span><h1>${t.headline}</h1><p>${t.lead}</p><div class="hero-actions"><a class="btn light" href="#services">${t.explore} ↗</a><a class="glass-link" href="#contact">${t.talk} ↗</a></div></div><aside class="edge-discovery" aria-label="${lang==='tr'?'Etkinlik keşfi':'Explore events'}"><div class="edge-wheel"><div class="edge-orbit" aria-hidden="true"></div><button type="button" class="edge-core" aria-label="${lang==='tr'?'Etkinlikleri keşfedin':'Explore events'}"><span class="core-ripples" aria-hidden="true"><i></i><i></i><i></i></span><svg class="core-arc-label" viewBox="0 0 430 430" aria-hidden="true"><defs><path id="discover-curve" d="M 215 400 A 185 185 0 0 1 215 30"/></defs><text><textPath href="#discover-curve" startOffset="50%" text-anchor="middle">${lang==='tr'?'Keşfedin':'Explore'}</textPath></text></svg></button>${[240,200,160,120].map((angle,i)=>{const r=angle*Math.PI/180;return `<div class="edge-item" style="--px:${Math.cos(r)};--py:${Math.sin(r)};--turn:${angle+90}deg"><button class="edge-petal" type="button" data-edge="${i}" aria-expanded="false" aria-controls="edge-tip-${i}" aria-label="${esc(t.eventTitles[i])}"><span>0${i+1}</span></button><div class="edge-tip" id="edge-tip-${i}" hidden><a href="#event/${i}">${t.eventTitles[i]} <span aria-hidden="true">↗</span></a></div></div>`;}).join('')}</div></aside></div><div class="hero-bottom"><span>${t.footer}</span><div class="video-controls"><span class="status" role="status"></span><button id="videoControl" aria-label="${t.playVideo}" title="${t.playVideo}"><span class="video-symbol is-play" aria-hidden="true"></span></button></div></div></div></section><section class="wrap feature" aria-label="${t.selectSlide}"><div class="slider"><div id="slides">${articles.map((a,i)=>`<a class="slide" href="#article/${a.id}" ${i?'hidden':''}><div class="slide-copy"><span class="eyebrow">${a[lang].tag}</span><h2>${a[lang].title}</h2><p>${a[lang].intro.split('. ')[0]}.</p><span class="read">${t.read} ↗</span></div><div class="slide-visual"><span class="visual-label">${['01 / '+t.serviceNames[2],'02 / '+t.serviceNames[0],'03 / '+t.serviceNames[1]][i]}</span></div></a>`).join('')}</div><div class="slider-controls"><div class="slider-buttons" id="dots">${articles.map((a,i)=>`<button aria-label="${esc(a[lang].title)}" aria-current="${i===0}">${i+1}</button>`).join('')}</div><div class="slider-buttons"><button id="previous" aria-label="${t.prev}">←</button><button id="next" aria-label="${t.next}">→</button><button id="pause">${t.pause}</button></div></div></div></section><section class="wrap" id="about" aria-label="${t.about}"><div class="stats">${['2.465','41.675+','370'].map((n,i)=>`<div class="stat"><strong>${lang==='en'?n.replaceAll('.',','):n}</strong><span>${t.statLabels[i]}</span></div>`).join('')}</div></section><section class="section wrap" id="services"><div class="section-top"><div><span class="eyebrow">${t.serviceTag}</span><h2>${t.serviceTitle}</h2></div><p>${t.serviceIntro}</p></div><div class="tabs" role="tablist" aria-label="${t.serviceTag}">${t.serviceNames.map((n,i)=>`<button role="tab" id="tab${i}" aria-controls="servicePanel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-tab="${i}">${n}</button>`).join('')}</div><div id="servicePanel" class="service-panel" role="tabpanel" aria-labelledby="tab0" tabindex="0"></div></section><section class="band" id="events"><div class="wrap section"><div class="section-top"><div><span class="eyebrow">${t.eventsTag}</span><h2>${t.eventsTitle}</h2></div><p>${t.eventsNote}</p></div><div class="event-filters" aria-label="${t.eventsTag}">${t.filterLabels.map((name,i)=>`<button type="button" data-filter="${i}" aria-pressed="${i===0}">${name}</button>`).join('')}</div><div class="event-count" role="status" id="eventCount">6 ${t.eventUnit}</div><div class="event-grid">${t.eventTitles.map((title,i)=>`<details class="event-card" data-kind="${i%2+1}"><summary><div class="event-top"><time class="event-date" datetime="${['2026-10-15','2026-10-22','2026-11-05','2026-11-19','2026-12-03','2026-12-17'][i]}"><b>${['15','22','05','19','03','17'][i]}</b><small>${t.eventDates[i]}</small></time><span class="event-format">${t.eventTypes[i]}</span></div><span class="event-title"><b>${title}</b><small>${t.example}</small></span><div class="event-bottom"><span>${t.detailsLabel}</span><span class="plus" aria-hidden="true">+</span></div></summary><div class="event-body">${t.eventBodies[i]}<p><a class="back" href="#contact">${t.talk} ↗</a></p></div></details>`).join('')}</div></div></section><section class="wrap section" id="insights"><div class="section-top"><div><span class="eyebrow">${t.blogTag}</span><h2>${t.blogTitle}</h2></div><p>${t.blogLead}</p></div><div class="blog-grid">${articles.map(card).join('')}</div></section><section class="wrap" id="contact"><div class="contact"><div><span class="eyebrow">${t.contact}</span><h2>${t.contactTitle}</h2><p>${t.contactLead}</p><p class="note">${t.demo}</p></div><div class="contact-cards"><a class="contact-card" href="tel:+902120000000"><span>${t.phone} ↗</span><strong>+90 (212) 000 00 00</strong></a><a class="contact-card" href="mailto:iletisim@example.com"><span>${t.email} ↗</span><strong>iletisim@example.com</strong></a></div></div></section>`;

const edgeItems=[...document.querySelectorAll('.edge-item')];
function closeEdge(){edgeItems.forEach(item=>{item.classList.remove('is-open');item.querySelector('.edge-tip').hidden=true;item.querySelector('button').setAttribute('aria-expanded','false');});}
function openEdge(index){closeEdge();const item=edgeItems[index];item.classList.add('is-open');item.querySelector('.edge-tip').hidden=false;item.querySelector('button').setAttribute('aria-expanded','true');}
edgeItems.forEach((item,i)=>{let delay;item.addEventListener('pointerenter',e=>{clearTimeout(delay);if(e.pointerType!=='touch')openEdge(i);});item.addEventListener('pointerleave',()=>{delay=setTimeout(()=>{if(!item.contains(document.activeElement)){item.classList.remove('is-open');item.querySelector('.edge-tip').hidden=true;item.querySelector('button').setAttribute('aria-expanded','false');}},180);});item.querySelector('button').addEventListener('click',()=>openEdge(i));item.addEventListener('focusin',()=>{clearTimeout(delay);openEdge(i);});item.addEventListener('focusout',e=>{if(!item.contains(e.relatedTarget))closeEdge();});item.addEventListener('keydown',e=>{if(e.key==='Escape'){closeEdge();item.querySelector('button').focus();closeEdge();}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();edgeItems[(i+(e.key==='ArrowDown'?1:3))%4].querySelector('button').focus();}});});
document.querySelector('.edge-core').onclick=()=>edgeItems[0].querySelector('button').focus();
const filters=[...document.querySelectorAll('[data-filter]')];filters.forEach(button=>button.onclick=()=>{const value=button.dataset.filter;filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('.event-card').forEach(card=>{card.hidden=value!=='0'&&card.dataset.kind!==value;if(!card.hidden)count++;});document.querySelector('#eventCount').textContent=count+' '+t.eventUnit;});
const tabs=[...document.querySelectorAll('[role=tab]')];function tab(i){tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1;});let panel=document.querySelector('#servicePanel');panel.setAttribute('aria-labelledby','tab'+i);panel.innerHTML=`<div><h3>${t.serviceHead[i]}</h3><p>${t.serviceDesc[i]}</p><a class="back" href="#article/${['learning','analysis','export'][i]}">${t.courseMore} ↗</a></div><ul>${t.serviceLists[i].map((x,j)=>`<li><span>0${j+1}</span>${x}</li>`).join('')}</ul>`;}tabs.forEach((b,i)=>{b.onclick=()=>tab(i);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;tab(n);tabs[n].focus();}}});tab(0);
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');const slider=document.querySelector('.slider'),slides=[...document.querySelectorAll('.slide')],dots=[...document.querySelectorAll('#dots button')],pause=document.querySelector('#pause');let index=0,paused=reduced.matches,timer,visible=false;function show(i){index=(i+3)%3;slides.forEach((s,j)=>s.hidden=j!==index);dots.forEach((d,j)=>d.setAttribute('aria-current',String(j===index)));}function schedule(){clearInterval(timer);if(visible&&!paused&&!document.hidden&&!slider.matches(':hover')&&!slider.contains(document.activeElement))timer=setInterval(()=>show(index+1),5000);}function pauseLabel(){pause.textContent=paused?t.play:t.pause;}dots.forEach((d,i)=>d.onclick=()=>{show(i);schedule();});document.querySelector('#previous').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);pause.onclick=()=>{paused=!paused;pauseLabel();schedule();};slider.onmouseenter=()=>clearInterval(timer);slider.onmouseleave=schedule;slider.onfocusin=()=>clearInterval(timer);slider.onfocusout=()=>setTimeout(schedule,0);pauseLabel();let observer;if('IntersectionObserver'in window){observer=new IntersectionObserver(e=>{visible=e[0].isIntersecting;schedule();},{threshold:.2});observer.observe(slider);}else{visible=true;schedule();}
const video=document.querySelector('video'),vc=document.querySelector('#videoControl'),status=document.querySelector('.status');let userPaused=reduced.matches||!!navigator.connection?.saveData,loaded=false;function vlabel(){const label=video.paused?t.playVideo:t.pauseVideo;vc.setAttribute('aria-label',label);vc.title=label;vc.innerHTML='<span class="video-symbol '+(video.paused?'is-play':'is-pause')+'" aria-hidden="true"></span>';}async function playVideo(){if(!loaded){video.src=videoAsset;loaded=true;}video.muted=true;try{await video.play();status.textContent='';}catch(e){status.textContent=t.playVideo;}vlabel();}vc.onclick=()=>{if(video.paused){userPaused=false;playVideo();}else{userPaused=true;video.pause();}};video.onplay=vlabel;video.onpause=vlabel;video.onerror=()=>{status.textContent=t.videoError;userPaused=true;vlabel();};if(!userPaused)playVideo();function visibility(){schedule();if(document.hidden)video.pause();else if(!userPaused)playVideo();}function motion(e){if(e.matches){paused=true;userPaused=true;video.pause();pauseLabel();schedule();}}document.addEventListener('visibilitychange',visibility);reduced.addEventListener('change',motion);cleanup=()=>{clearInterval(timer);observer?.disconnect();document.removeEventListener('visibilitychange',visibility);reduced.removeEventListener('change',motion);video.pause();video.removeAttribute('src');video.load();};}
