const pointerFine=window.matchMedia('(hover: hover) and (pointer: fine)');
const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
const ring=document.querySelector('.cursor-ring'),ambient=document.querySelector('.ambient');
let pointerFrame=0,lastPointer=null;
document.addEventListener('pointermove',event=>{if(!pointerFine.matches||motionPreference.matches||event.pointerType==='touch')return;lastPointer={x:event.clientX,y:event.clientY,target:event.target};if(pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;const {x,y,target}=lastPointer;ring.style.transform=`translate(${x}px,${y}px)`;ring.classList.add('visible');ring.classList.toggle('active',!!target.closest('a,button,summary'));const card=target.closest('.service-panel,.blog-card,.event-card,.contact-card');if(card){const rect=card.getBoundingClientRect();card.style.setProperty('--pointer-x',(x-rect.left)+'px');card.style.setProperty('--pointer-y',(y-rect.top)+'px');}ambient.style.setProperty('--drift-x',((x/innerWidth-.5)*22)+'px');ambient.style.setProperty('--drift-y',((y/innerHeight-.5)*18)+'px');});},{passive:true});
document.documentElement.addEventListener('pointerleave',()=>ring.classList.remove('visible'));
window.addEventListener('blur',()=>ring.classList.remove('visible'));
motionPreference.addEventListener('change',()=>{ring.classList.remove('visible');ambient.style.removeProperty('--drift-x');ambient.style.removeProperty('--drift-y');});
window.addEventListener('hashchange',()=>render());render();

// Reading progress applies only to an open article.
const readingProgress=document.createElement('div');
readingProgress.className='reading-progress';
readingProgress.setAttribute('aria-hidden','true');
document.body.appendChild(readingProgress);
let readingFrame=0;
function updateReadingProgress(){readingFrame=0;const article=document.querySelector('article.article');if(!article){readingProgress.style.transform='scaleX(0)';return;}const start=article.getBoundingClientRect().top+window.scrollY;const distance=article.offsetHeight-window.innerHeight;const value=distance>0?Math.min(1,Math.max(0,(window.scrollY-start)/distance)):1;readingProgress.style.transform='scaleX('+value+')';}
function queueReadingProgress(){if(!readingFrame)readingFrame=requestAnimationFrame(updateReadingProgress);}
window.addEventListener('scroll',queueReadingProgress,{passive:true});
window.addEventListener('resize',queueReadingProgress);
window.addEventListener('hashchange',queueReadingProgress);
new MutationObserver(queueReadingProgress).observe(document.querySelector('main'),{childList:true});
queueReadingProgress();
